"""
Extension planning and provenance machinery.

The functions and data structures in this module reconstruct *exactly* the
extension selection logic that :meth:`PKIArchitecture.get_cert` uses when it
issues a certificate, but without performing any signing or touching the
certificate cache. This makes it possible to explain where every extension in
a not-yet-issued certificate comes from:

* autogenerated ``subjectKeyIdentifier`` / ``authorityKeyIdentifier``,
* extensions provisioned by certificate profile plugins,
* extensions declared explicitly in the certificate spec, and
* extensions inherited through (possibly nested) certificate templates,
  including entries that were suppressed because of duplicate handling.

The actual signing code in
:class:`~certomancer.registry.pki_arch.PKIArchitecture`
and the explanation API share the same planner, so an explanation can never
silently drift away from real issuance behaviour.
"""

from dataclasses import dataclass, field
from enum import Enum
from typing import (
    TYPE_CHECKING,
    Any,
    Dict,
    List,
    Optional,
    Tuple,
)

from asn1crypto import core, x509

from ..config_utils import ConfigurationError
from ..services import CertomancerServiceError
from .common import CertLabel, CertomancerObjectNotFoundError, PluginLabel

if TYPE_CHECKING:
    from .issued.general import ExtensionSpec, IssuedItemSpec
    from .pki_arch import PKIArchitecture

__all__ = [
    'ExtensionSource',
    'ConfigExtensionProvenance',
    'ConfigSuppressionReason',
    'SuppressedConfigExtension',
    'ExtensionConfigTrace',
    'ExtensionOrigin',
    'SuppressedExtension',
    'ExplainedExtension',
    'ExtensionExplanation',
    'normalise_extension_id',
    'plan_cert_extensions',
    'build_auto_ski_aki',
]


class ExtensionSource(str, Enum):
    """Where an extension included in a certificate came from."""

    AUTO = 'auto'
    """Autogenerated value (SKI/AKI)."""

    PROFILE = 'profile'
    """Provisioned by a certificate profile plugin."""

    CONFIG = 'config'
    """Declared in the certificate spec, either directly or via a template."""


class ConfigSuppressionReason(str, Enum):
    """Why an extension entry disappeared while merging template config."""

    TEMPLATE_DUPLICATE = 'template_duplicate'
    """A later declaration replaced an earlier one while combining explicit
    extensions with template extensions in unique mode."""


# ---------------------------------------------------------------------------
# Config-time provenance (populated while certificate specs are parsed)
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class ConfigExtensionProvenance:
    """
    Provenance information for a single entry in a spec's ``extensions`` list.

    Entries declared directly in the spec itself have :attr:`inherited` set to
    ``False``. Entries copied in through a template record the label of the
    spec in which the extension was originally declared, and the chain of
    template references that was walked to get there (nearest template first).
    """

    declared_in: CertLabel
    inherited: bool = False
    template_chain: Tuple[CertLabel, ...] = ()


@dataclass(frozen=True)
class SuppressedConfigExtension:
    """
    An extension entry that was dropped while merging template extensions in
    unique mode, so it never made it into the spec's effective ``extensions``
    list.
    """

    raw_id: str
    reason: ConfigSuppressionReason
    provenance: ConfigExtensionProvenance


@dataclass
class ExtensionConfigTrace:
    """
    Bookkeeping collected while the certificate specs of an architecture are
    being parsed. The origin lists are aligned index-by-index with the
    corresponding spec's ``extensions`` list.
    """

    origins: Dict[CertLabel, List[ConfigExtensionProvenance]] = field(
        default_factory=dict
    )
    suppressed: Dict[CertLabel, List[SuppressedConfigExtension]] = field(
        default_factory=dict
    )

    def record_origins(
        self, label: CertLabel, origins: List[ConfigExtensionProvenance]
    ):
        self.origins[label] = origins

    def record_suppressed(
        self, label: CertLabel, entries: List[SuppressedConfigExtension]
    ):
        if entries:
            self.suppressed.setdefault(label, []).extend(entries)

    def get_origins(
        self, label: CertLabel
    ) -> List[ConfigExtensionProvenance]:
        return self.origins.get(label, [])

    def get_suppressed(
        self, label: CertLabel
    ) -> List[SuppressedConfigExtension]:
        return self.suppressed.get(label, [])


# ---------------------------------------------------------------------------
# Explanation data model
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class ExtensionOrigin:
    """
    Explains the origin of a single extension in the final certificate.
    """

    source: ExtensionSource
    raw_id: str
    dotted_oid: str
    native_oid: str
    # used for source == CONFIG
    declared_in: Optional[CertLabel] = None
    inherited: bool = False
    template_chain: Tuple[CertLabel, ...] = ()
    # used for source == PROFILE
    profile_label: Optional[PluginLabel] = None
    from_issuer_profile: bool = False
    # used for source == AUTO
    auto_extension: Optional[str] = None
    auto_reason: Optional[str] = None


@dataclass(frozen=True)
class SuppressedExtension:
    """
    An extension candidate that lost out against another candidate with the
    same extension ID, and therefore does not appear in the certificate.
    """

    raw_id: str
    dotted_oid: str
    native_oid: str
    stage: str
    reason: str
    detail: str
    origin: ExtensionOrigin
    winner_index: Optional[int] = None


@dataclass(frozen=True)
class ExplainedExtension:
    """
    A single extension that will be included in the issued certificate,
    together with everything there is to say about its provenance.
    """

    index: int
    raw_id: str
    dotted_oid: str
    native_oid: str
    critical: bool
    origin: ExtensionOrigin
    extension_der: bytes
    value_der: bytes
    overrides: Tuple[SuppressedExtension, ...] = ()


@dataclass(frozen=True)
class ExtensionExplanation:
    """
    Full explanation of the extension selection process for one certificate
    spec.
    """

    cert_label: CertLabel
    unique_extensions: bool
    extensions: Tuple[ExplainedExtension, ...]
    suppressed: Tuple[SuppressedExtension, ...]
    warnings: Tuple[str, ...] = ()

    def as_dict(self) -> Dict[str, Any]:
        """Serialise the explanation to plain Python types (for YAML/JSON)."""

        def _origin(o: ExtensionOrigin):
            return {
                'source': o.source.value,
                'raw_id': o.raw_id,
                'dotted_oid': o.dotted_oid,
                'native_oid': o.native_oid,
                'declared_in': _label(o.declared_in),
                'inherited': o.inherited,
                'template_chain': [str(lbl) for lbl in o.template_chain],
                'profile_label': _label(o.profile_label),
                'from_issuer_profile': o.from_issuer_profile,
                'auto_extension': o.auto_extension,
                'auto_reason': o.auto_reason,
            }

        def _suppressed(s: SuppressedExtension):
            return {
                'raw_id': s.raw_id,
                'dotted_oid': s.dotted_oid,
                'native_oid': s.native_oid,
                'stage': s.stage,
                'reason': s.reason,
                'detail': s.detail,
                'origin': _origin(s.origin),
                'winner_index': s.winner_index,
            }

        return {
            'cert_label': str(self.cert_label),
            'unique_extensions': self.unique_extensions,
            'warnings': list(self.warnings),
            'extensions': [
                {
                    'index': ext.index,
                    'raw_id': ext.raw_id,
                    'dotted_oid': ext.dotted_oid,
                    'native_oid': ext.native_oid,
                    'critical': ext.critical,
                    'origin': _origin(ext.origin),
                    'extension_der_hex': ext.extension_der.hex(),
                    'value_der_hex': ext.value_der.hex(),
                    'overrides': [_suppressed(s) for s in ext.overrides],
                }
                for ext in self.extensions
            ],
            'suppressed': [_suppressed(s) for s in self.suppressed],
        }


def _label(value) -> Optional[str]:
    return None if value is None else str(value)


# ---------------------------------------------------------------------------
# OID handling
# ---------------------------------------------------------------------------


def normalise_extension_id(raw_id: str) -> Tuple[str, str, Optional[str]]:
    """
    Normalise an extension identifier.

    Takes either an ``asn1crypto`` alias (e.g. ``'basic_constraints'``) or a
    dotted numeric OID (e.g. ``'2.5.29.19'``), and returns a triple
    ``(dotted_oid, native_label, warning)`` where ``warning`` is ``None`` when
    the identifier could be parsed. Both forms of the same OID normalise to
    the same dotted value.
    """

    try:
        oid = x509.ExtensionId(raw_id)
    except ValueError:
        return raw_id, raw_id, (
            f"Extension identifier '{raw_id}' could not be parsed as an OID; "
            "reporting it verbatim."
        )
    return oid.dotted, oid.native, None


# ---------------------------------------------------------------------------
# Autogenerated SKI/AKI
# ---------------------------------------------------------------------------


def _effective_subject_key_id(
    arch: 'PKIArchitecture', spec: 'IssuedItemSpec'
) -> Tuple[bytes, str]:
    """
    Predict the effective subject key identifier of a certificate without
    issuing it: an explicit ``key_identifier`` extension in the spec overrides
    the default SHA-1 hash of the subject public key.
    """

    # asn1crypto indexes named extensions by overwriting attributes as it
    # walks the extension list, so in duplicate-allowed mode the *last*
    # key_identifier entry is the one whose value ends up being used.
    for ext_spec in reversed(spec.extensions):
        if normalise_extension_id(ext_spec.id)[0] != '2.5.29.14':
            continue
        explicit = ext_spec.to_asn1(arch, x509.Extension)
        return (
            explicit['extn_value'].native,
            "explicit 'key_identifier' extension overrides the default "
            "SHA-1 subject key identifier",
        )
    ski = arch.key_set[spec.subject_key].public_key_info.sha1
    return (
        ski,
        "SHA-1 hash of the subject public key (default subject key "
        "identifier)",
    )


def build_auto_ski_aki(
    arch: 'PKIArchitecture', spec: 'IssuedItemSpec'
) -> Tuple[
    Tuple[str, x509.Extension, str],
    Tuple[str, x509.Extension, str],
]:
    """
    Build the autogenerated SKI and AKI extension candidates.

    The selection rules mirror those in :meth:`PKIArchitecture.get_cert`
    exactly, but this function never signs a certificate and never writes to
    the architecture's certificate cache.

    :return:
        two ``(raw_id, extension, reason)`` triples, one for the SKI and one
        for the AKI.
    """

    subject_key = arch.key_set[spec.subject_key]
    ski = subject_key.public_key_info.sha1
    ski_extension = x509.Extension(
        {
            'extn_id': 'key_identifier',
            'critical': False,
            'extn_value': core.OctetString(ski),
        }
    )
    ski_reason = (
        "autogenerated subject key identifier: SHA-1 hash of the subject "
        "public key"
    )

    aki, aki_reason = _resolve_aki(arch, spec, ski)
    aki_value = x509.AuthorityKeyIdentifier({'key_identifier': aki})
    aki_extension = x509.Extension(
        {
            'extn_id': 'authority_key_identifier',
            'critical': False,
            'extn_value': aki_value,
        }
    )
    return (
        ('key_identifier', ski_extension, ski_reason),
        ('authority_key_identifier', aki_extension, aki_reason),
    )


def _resolve_aki(
    arch: 'PKIArchitecture', spec: 'IssuedItemSpec', ski: bytes
) -> Tuple[bytes, str]:
    if spec.self_signed:
        # Mirror get_cert() exactly: for self-signed certificates the AKI is
        # copied from the internal default SKI value (the SHA-1 hash of the
        # subject public key), even if an explicit key_identifier extension
        # overrides the encoded SKI.
        return (
            ski,
            "self-signed certificate: AKI is copied from the default subject "
            "key identifier (the SHA-1 hash of the subject public key)",
        )
    try:
        issuer_cert_lbl = spec.resolve_issuer_cert(arch)
    except CertomancerServiceError:
        return _fallback_aki(arch, spec)
    if issuer_cert_lbl == spec.label:
        raise ConfigurationError(
            f"Self-reference detected: issuer cert for {spec.label} resolves "
            f"to itself, but the certificate is not self-signed: Authority "
            f"key: {spec.authority_key}; subject key: {spec.subject_key}."
        )
    cached_issuer = arch.peek_cached_cert(issuer_cert_lbl)
    if cached_issuer is not None:
        return (
            cached_issuer.key_identifier_value,
            f"copied from the key identifier extension of the already issued "
            f"issuer certificate '{issuer_cert_lbl}'",
        )
    # Predict the issuer's effective SKI from its spec/key material instead
    # of signing the issuer certificate.
    issuer_spec = arch.get_cert_spec(issuer_cert_lbl)
    aki, detail = _effective_subject_key_id(arch, issuer_spec)
    if detail.startswith('explicit'):
        reason = (
            f"copied from the explicit 'key_identifier' extension of issuer "
            f"certificate '{issuer_cert_lbl}', which has not been issued yet"
        )
    else:
        reason = (
            f"derived from issuer certificate '{issuer_cert_lbl}' before it "
            f"is issued: {detail}"
        )
    return aki, reason


def _fallback_aki(
    arch: 'PKIArchitecture', spec: 'IssuedItemSpec'
) -> Tuple[bytes, str]:
    authority_key = arch.key_set[spec.authority_key]
    return (
        authority_key.public_key_info.sha1,
        "no unambiguous issuer certificate available: SHA-1 hash of the "
        "authority public key used as the default AKI",
    )


# ---------------------------------------------------------------------------
# Profile collection (mirrors CertProfilePluginRegistry.apply_profiles, but
# keeps provenance information)
# ---------------------------------------------------------------------------


def _collect_profile_candidates(
    arch: 'PKIArchitecture', spec: 'IssuedItemSpec'
) -> List[Tuple['ExtensionSpec', ExtensionOrigin]]:
    candidates: List[Tuple['ExtensionSpec', ExtensionOrigin]] = []

    for profile, params in spec.profiles.items():
        plugin = arch.profile_registry[profile]
        for ext_spec in plugin.extensions_for_self(arch, params, spec):
            dotted, native, _ = normalise_extension_id(ext_spec.id)
            candidates.append(
                (
                    ext_spec.to_asn1(arch, x509.Extension),
                    ExtensionOrigin(
                        source=ExtensionSource.PROFILE,
                        raw_id=ext_spec.id,
                        dotted_oid=dotted,
                        native_oid=native,
                        profile_label=profile,
                        from_issuer_profile=False,
                    ),
                )
            )

    try:
        issuer_cert_lbl = spec.resolve_issuer_cert(arch)
        issuer_spec = arch.get_cert_spec(issuer_cert_lbl)
    except CertomancerObjectNotFoundError:
        issuer_spec = None

    if issuer_spec is not None:
        for profile, params in issuer_spec.profiles.items():
            plugin = arch.profile_registry[profile]
            for ext_spec in plugin.extensions_for_issued(
                arch, params, issuer_spec, spec
            ):
                dotted, native, _ = normalise_extension_id(ext_spec.id)
                candidates.append(
                    (
                        ext_spec.to_asn1(arch, x509.Extension),
                        ExtensionOrigin(
                            source=ExtensionSource.PROFILE,
                            raw_id=ext_spec.id,
                            dotted_oid=dotted,
                            native_oid=native,
                            profile_label=profile,
                            from_issuer_profile=True,
                        ),
                    )
                )
    return candidates


def _config_origin(
    arch: 'PKIArchitecture',
    spec: 'IssuedItemSpec',
    position: int,
    raw_id: str,
) -> ExtensionOrigin:
    dotted, native, _ = normalise_extension_id(raw_id)
    provenance = arch.get_extension_provenance(spec.label, position)
    return ExtensionOrigin(
        source=ExtensionSource.CONFIG,
        raw_id=raw_id,
        dotted_oid=dotted,
        native_oid=native,
        declared_in=provenance.declared_in,
        inherited=provenance.inherited,
        template_chain=provenance.template_chain,
    )


def _auto_origin(raw_id: str, reason: str) -> ExtensionOrigin:
    dotted, native, _ = normalise_extension_id(raw_id)
    return ExtensionOrigin(
        source=ExtensionSource.AUTO,
        raw_id=raw_id,
        dotted_oid=dotted,
        native_oid=native,
        auto_extension=raw_id,
        auto_reason=reason,
    )


# ---------------------------------------------------------------------------
# Main planner
# ---------------------------------------------------------------------------


def plan_cert_extensions(
    arch: 'PKIArchitecture', spec: 'IssuedItemSpec'
) -> ExtensionExplanation:
    """
    Reconstruct the full extension selection process for ``spec``.

    The returned :class:`ExtensionExplanation` lists the extensions in the
    exact order (and with the exact values) in which they would be encoded
    into the certificate by :meth:`PKIArchitecture.get_cert`, together with
    provenance and override information for each of them.
    """

    warnings: List[str] = []

    ski_candidate, aki_candidate = build_auto_ski_aki(arch, spec)
    auto_candidates = [
        (ski_candidate[1], _auto_origin(ski_candidate[0], ski_candidate[2])),
        (aki_candidate[1], _auto_origin(aki_candidate[0], aki_candidate[2])),
    ]

    config_candidates = [
        (
            ext_spec.to_asn1(arch, x509.Extension),
            _config_origin(arch, spec, pos, ext_spec.id),
        )
        for pos, ext_spec in enumerate(spec.extensions)
    ]

    suppressed: List[SuppressedExtension] = []
    # winner index -> suppression records, keyed by the *final* position of
    # the surviving extension so alias/numeric-OID variants stay accurate
    overrides_by_index: Dict[int, List[SuppressedExtension]] = {}

    if spec.unique_extensions:
        planned: List[Tuple[x509.Extension, ExtensionOrigin]] = list(
            auto_candidates
        )
        profile_candidates = _collect_profile_candidates(arch, spec)
        # dict semantics: later candidates with the same raw extension ID
        # replace earlier ones, matching _collect_extensions() exactly.
        indexed: Dict[str, int] = {
            origin.raw_id: idx for idx, (_, origin) in enumerate(planned)
        }
        # parallel lookup on the canonical numeric OID, so that aliases and
        # dotted spellings of the same extension are still recognised as
        # override relationships in the explanation
        indexed_dotted: Dict[str, int] = {
            origin.dotted_oid: idx
            for idx, (_, origin) in enumerate(planned)
        }
        for ext_asn1, origin in profile_candidates + config_candidates:
            if origin.raw_id in indexed:
                winner_pos = indexed[origin.raw_id]
                # capture the *incumbent* entry's origin before replacing it,
                # since the suppression record must describe who lost out
                incumbent_origin = planned[winner_pos][1]
                suppressed_entry = _suppression_entry(
                    origin=incumbent_origin,
                    stage='unique_resolution',
                    detail=(
                        f"extension '{origin.raw_id}' already supplied by a "
                        f"lower-precedence source "
                        f"({incumbent_origin.source.value}); explicit config "
                        "wins over profiles and templates, profiles win over "
                        "autogenerated SKI/AKI"
                    ),
                    winner_index=winner_pos,
                )
                suppressed.append(suppressed_entry)
                overrides_by_index.setdefault(winner_pos, []).append(
                    suppressed_entry
                )
                planned[winner_pos] = (ext_asn1, origin)
            elif origin.dotted_oid in indexed_dotted:
                # same numeric OID, different identifier spelling: issuance
                # treats these as distinct entries (both are encoded), but
                # the explanation records the precedence relationship
                winner_pos = indexed_dotted[origin.dotted_oid]
                winner_origin = planned[winner_pos][1]
                suppressed_entry = SuppressedExtension(
                    raw_id=origin.raw_id,
                    dotted_oid=origin.dotted_oid,
                    native_oid=origin.native_oid,
                    stage='unique_resolution',
                    reason='same_oid_different_identifier',
                    detail=(
                        f"'{origin.raw_id}' denotes the same OID "
                        f"({origin.dotted_oid}) as the already present "
                        f"'{winner_origin.raw_id}'; raw-identifier "
                        "deduplication keeps both entries, but this later "
                        f"{origin.source.value} declaration takes precedence "
                        "for the extension's effective critical flag and value."
                    ),
                    origin=origin,
                    winner_index=winner_pos,
                )
                suppressed.append(suppressed_entry)
                overrides_by_index.setdefault(winner_pos, []).append(
                    suppressed_entry
                )
                new_pos = len(planned)
                indexed[origin.raw_id] = new_pos
                # the newest spelling is the effective one from now on
                indexed_dotted[origin.dotted_oid] = new_pos
                planned.append((ext_asn1, origin))
            else:
                indexed[origin.raw_id] = len(planned)
                indexed_dotted[origin.dotted_oid] = len(planned)
                planned.append((ext_asn1, origin))
    else:
        if spec.profiles:
            warnings.append(
                "unique_extensions is false: certificate profiles are not "
                "applied in duplicate-allowed mode, so "
                f"{len(spec.profiles)} configured profile(s) were ignored."
            )
        # no profiles in non-unique mode; order mirrors _collect_extensions()
        planned = list(auto_candidates) + config_candidates

    explained_exts: List[ExplainedExtension] = []

    # Second, OID-aware pass: issuance deduplicates on the raw identifier
    # string, so two entries that refer to the same OID through different
    # spellings (an asn1crypto alias vs. a dotted numeric OID) both survive.
    # In unique mode they are nevertheless conflicting declarations, so we
    # record the precedence relationship here without touching the encoded
    # output.
    dotted_groups: Dict[str, List[int]] = {}
    for index, (_, origin) in enumerate(planned):
        dotted_groups.setdefault(origin.dotted_oid, []).append(index)
    for dotted_oid, positions in dotted_groups.items():
        if len(positions) < 2:
            continue
        if not spec.unique_extensions:
            warnings.append(
                f"OID {dotted_oid} occurs {len(positions)} times; duplicate "
                "extensions are allowed because unique_extensions is false, "
                "so all occurrences are encoded into the certificate."
            )
            continue
        winner_index = positions[-1]
        winner_origin = planned[winner_index][1]
        already_recorded = any(
            entry.winner_index == winner_index
            and entry.dotted_oid == dotted_oid
            for entry in suppressed
        )
        if already_recorded:
            # the unique-resolution loop already described this relationship
            continue
        for losing_index in positions[:-1]:
            losing_origin = planned[losing_index][1]
            suppressed_entry = SuppressedExtension(
                raw_id=losing_origin.raw_id,
                dotted_oid=dotted_oid,
                native_oid=losing_origin.native_oid,
                stage='oid_alias_resolution',
                reason='same_oid_different_identifier',
                detail=(
                    f"'{losing_origin.raw_id}' and "
                    f"'{winner_origin.raw_id}' denote the same OID "
                    f"({dotted_oid}); both survive at the raw-identifier "
                    "level, but precedence-wise the later declaration from "
                    f"{winner_origin.source.value} takes over the extension's "
                    "role (in particular its critical flag and value)."
                ),
                origin=losing_origin,
                winner_index=winner_index,
            )
            suppressed.append(suppressed_entry)
            overrides_by_index.setdefault(winner_index, []).append(
                suppressed_entry
            )
        warnings.append(
            f"OID {dotted_oid} is declared {len(positions)} times using "
            "different identifier spellings; raw-identifier deduplication "
            "leaves all of them in the certificate, but the effective "
            f"critical flag/value follow '{winner_origin.raw_id}' (the last "
            "declaration)."
        )

    # config-time suppressions (template merging) never made it into the spec;
    # surface them separately with a pointer to the surviving extension.
    raw_id_to_index = {
        origin.raw_id: idx
        for idx, (_, origin) in enumerate(planned)
    }
    for cfg_suppressed in arch.get_suppressed_config_extensions(spec.label):
        dotted, native, _ = normalise_extension_id(cfg_suppressed.raw_id)
        prov = cfg_suppressed.provenance
        origin = ExtensionOrigin(
            source=ExtensionSource.CONFIG,
            raw_id=cfg_suppressed.raw_id,
            dotted_oid=dotted,
            native_oid=native,
            declared_in=prov.declared_in,
            inherited=prov.inherited,
            template_chain=prov.template_chain,
        )
        winner_index = raw_id_to_index.get(cfg_suppressed.raw_id)
        suppressed_entry = SuppressedExtension(
            raw_id=cfg_suppressed.raw_id,
            dotted_oid=dotted,
            native_oid=native,
            stage='template_merge',
            reason=cfg_suppressed.reason.value,
            detail=(
                "dropped while merging explicit extensions with template "
                "extensions in unique mode: the first declaration of "
                f"'{cfg_suppressed.raw_id}' wins, and this entry was "
                "declared later"
            ),
            origin=origin,
            winner_index=winner_index,
        )
        suppressed.append(suppressed_entry)
        if winner_index is not None:
            overrides_by_index.setdefault(winner_index, []).append(
                suppressed_entry
            )

    for index, (ext_asn1, origin) in enumerate(planned):
        raw_id = ext_asn1['extn_id'].native
        dotted, native, oid_warning = normalise_extension_id(raw_id)
        if oid_warning is not None and oid_warning not in warnings:
            warnings.append(oid_warning)
        explained_exts.append(
            ExplainedExtension(
                index=index,
                raw_id=raw_id,
                dotted_oid=dotted,
                native_oid=native,
                critical=bool(ext_asn1['critical'].native),
                origin=origin,
                extension_der=ext_asn1.dump(),
                value_der=ext_asn1['extn_value'].contents,
                overrides=tuple(overrides_by_index.get(index, ())),
            )
        )

    return ExtensionExplanation(
        cert_label=spec.label,
        unique_extensions=spec.unique_extensions,
        extensions=tuple(explained_exts),
        suppressed=tuple(suppressed),
        warnings=tuple(warnings),
    )


def _suppression_entry(
    origin: ExtensionOrigin,
    stage: str,
    detail: str,
    winner_index: Optional[int],
) -> SuppressedExtension:
    return SuppressedExtension(
        raw_id=origin.raw_id,
        dotted_oid=origin.dotted_oid,
        native_oid=origin.native_oid,
        stage=stage,
        reason='duplicate_extension_id',
        detail=detail,
        origin=origin,
        winner_index=winner_index,
    )
